    size_t i;
    adcs_vec3_t axis;
    double j_omega;
    adcs_vec3_t term;

    if (momentum_body_nms == NULL) {
        return ADCS_E_NULL;
    }
    *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
    if (wheels == NULL) {
        return ADCS_E_NULL;
    }
    if ((count < 1U) || (count > 16U)) {
        return ADCS_E_RANGE;
    }

    /* Validate the complete array first. */
    for (i = 0; i < count; i++) {
        if ((!adcs_is_finite_vec3(&wheels[i].axis_body)) ||
            (!isfinite(wheels[i].inertia_kg_m2)) ||
            (!isfinite(wheels[i].speed_rad_s))) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        if (!(wheels[i].inertia_kg_m2 > 0.0)) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
        if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
            *momentum_body_nms = (adcs_vec3_t){0.0, 0.0, 0.0};
            return ADCS_E_RANGE;
        }
    }

    /* Accumulate in index order. */
    for (i = 0; i < count; i++) {
        (void)adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis);
        j_omega = wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s;
        term = adcs_vec3_scale(&axis, j_omega);
        *momentum_body_nms = adcs_vec3_add(momentum_body_nms, &term);
    }

    return ADCS_OK;
}

